'use strict';
window.ReferenceNotes=(()=>{
 const kinds=['rule','grammar'],pages={rule:1,grammar:1},queries={rule:'',grammar:''},size=9;
 const patterns={
  '본 적이 없다':['-(으)ㄴ 적이 없다','have never done something; 본 적이 없다 = have never seen it'],
  '한 개밖에 없다':['밖에 + negative','only; 한 개밖에 없다 = there is only one'],
  '걸으면':['-(으)면','if / when; 걸으면 = if you walk (걷다 → 걸으면)'],
  '자기를 지키는':['-는 + noun','present-tense verb modifier; 자기를 지키는 = protecting oneself'],
  '-(으)ㄴ 지 … 됐다':['-(으)ㄴ 지','it has been [length of time] since … / прошло время с тех пор как'],
  '-(으)ㄴ 지':['-(으)ㄴ 지','it has been [length of time] since … / прошло время с тех пор как']
 };
 const phrases=new Set(['처럼','위해','뒤에','그 중에는','빼고','그러나','그러면','그러니까','왜냐하면']);
 function normalize(input){const seen=new Set();return(Array.isArray(input)?input:[]).filter(n=>n&&typeof n.id==='string'&&kinds.includes(n.kind)&&typeof n.title==='string'&&n.title.trim()&&!seen.has(n.id)&&seen.add(n.id)).map(n=>({id:n.id,kind:n.kind,title:n.title,text:typeof n.text==='string'?n.text:'',sourceIds:Array.isArray(n.sourceIds)?n.sourceIds.filter(s=>typeof s==='string'):[],deleted:!!n.deleted,createdAt:typeof n.createdAt==='string'?n.createdAt:'',updatedAt:typeof n.updatedAt==='string'?n.updatedAt:'',...(n.studyRef&&typeof n.studyRef==='object'?{studyRef:{chapter:n.studyRef.chapter,part:n.studyRef.part,date:n.studyRef.date}}:{})}))}
 function extract(list){const out=new Map();for(const w of list){if(w.deleted||w.hanjaRef)continue;const title=w.korean||'',match=patterns[title];if(!match&&!phrases.has(title)&&w.studyRef?.kind!=='grammar'&&w.kind!=='grammar'&&!/^[-−–]/.test(title))continue;const name=match?.[0]||title,key='grammar:'+name.replace(/\s+/g,' ').trim();if(out.has(key)){out.get(key).sourceIds.push(w.id);continue}out.set(key,{id:key,kind:'grammar',title:name,text:match?.[1]||[w.answer,w.note].filter(Boolean).join('\n\n'),sourceIds:[w.id],deleted:false,createdAt:'',updatedAt:''})}return[...out.values()]}
 function sync(){const before=JSON.stringify(state.referenceNotes),notes=normalize(state.referenceNotes),ids=new Set(notes.map(n=>n.id));const seed={id:'rule:negation-contrast',kind:'rule',title:'-지 않고 / -지 말고',text:'-지 않고 describes something you don’t/didn’t do, while doing something else.\n\n-지 말고 tells someone “don’t do A; do B instead.”',sourceIds:[],deleted:false,createdAt:'',updatedAt:''};for(const n of[seed,...extract(words)])if(!ids.has(n.id)){notes.push(n);ids.add(n.id)}state.referenceNotes=notes;return before!==JSON.stringify(notes)}
 function edit(kind,id){const note=state.referenceNotes.find(n=>n.id===id);showDialog(`<h2>${note?'Edit entry':kind==='grammar'?'Add grammar structure':'Add rule'}</h2><form id="referenceForm"><label for="referenceTitle">Title</label><input id="referenceTitle" required maxlength="300" value="${e(note?.title||'')}" placeholder="${kind==='grammar'?'e.g. (으)면서':'Rule title'}"><label for="referenceText">Meaning, explanation & examples</label><textarea id="referenceText" rows="8" required>${e(note?.text||'')}</textarea><div class="reference-form-actions"><button class="btn primary" type="submit">Save entry</button><button class="small-btn" type="button" id="referenceCancel">Cancel</button></div></form>`);$('#referenceCancel').onclick=()=>$('#dialog').close();$('#referenceForm').onsubmit=event=>{event.preventDefault();const title=$('#referenceTitle').value.trim(),text=$('#referenceText').value.trim();if(!title||!text)return;const stamp=new Date().toISOString();if(note)Object.assign(note,{title,text,updatedAt:stamp});else state.referenceNotes.push({id:'note:'+crypto.randomUUID(),kind,title,text,sourceIds:[],deleted:false,createdAt:stamp,updatedAt:stamp});save();$('#dialog').close();render(kind);toast('Entry saved.')}}
 function render(kind){if(sync())save();const notes=state.referenceNotes.filter(n=>n.kind===kind),query=queries[kind].toLocaleLowerCase(),active=notes.filter(n=>!n.deleted),filtered=active.filter(n=>(n.title+' '+n.text).toLocaleLowerCase().includes(query)),total=Math.max(1,Math.ceil(filtered.length/size));pages[kind]=Math.max(1,Math.min(pages[kind],total));const page=pages[kind],shown=filtered.slice((page-1)*size,page*size),deleted=notes.filter(n=>n.deleted);$('#hubBody').innerHTML=`<section class="reference-library"><div class="reference-toolbar"><label class="reference-search" for="referenceSearch"><span>Search entries</span><input type="search" id="referenceSearch" placeholder="Search entries" value="${e(queries[kind])}"></label><button class="btn primary" id="referenceAdd">${kind==='grammar'?'Add grammar structure':'Add rule'}</button></div><div class="reference-grid">${shown.map(n=>`<article class="reference-card"><details><summary><span translate="no" data-user-content lang="ko">${e(n.title)}</span><span class="reference-reveal">Show meaning</span></summary><div class="reference-explanation" translate="no" data-user-content>${e(n.text)}</div></details><div class="reference-card-actions"><button class="small-btn" data-reference-edit="${e(n.id)}">Edit</button><button class="text-link" data-reference-delete="${e(n.id)}">Delete</button></div></article>`).join('')||'<p class="reference-empty">No matching entries.</p>'}</div><nav class="reference-pagination" aria-label="Entry pages"><button class="small-btn" id="referencePrev" ${page===1?'disabled':''}>Previous</button><span>PAGE ${page} / ${total}</span><button class="small-btn" id="referenceNext" ${page===total?'disabled':''}>Next</button></nav>${deleted.length?`<details class="reference-trash"><summary>Deleted entries (${deleted.length})</summary>${deleted.map(n=>`<div><span translate="no" data-user-content>${e(n.title)}</span><button class="small-btn" data-reference-restore="${e(n.id)}">Restore</button></div>`).join('')}</details>`:''}</section>`;$('#referenceAdd').onclick=()=>edit(kind);$('#referenceSearch').oninput=event=>{const pos=event.target.selectionStart;queries[kind]=event.target.value;pages[kind]=1;render(kind);const input=$('#referenceSearch');input.focus();try{input.setSelectionRange(pos,pos)}catch{}};$('#referencePrev').onclick=()=>{pages[kind]--;render(kind)};$('#referenceNext').onclick=()=>{pages[kind]++;render(kind)};document.querySelectorAll('[data-reference-edit]').forEach(b=>b.onclick=()=>edit(kind,b.dataset.referenceEdit));for(const action of['delete','restore'])document.querySelectorAll(`[data-reference-${action}]`).forEach(b=>b.onclick=()=>{const note=notes.find(n=>n.id===b.getAttribute('data-reference-'+action));note.deleted=action==='delete';note.updatedAt=new Date().toISOString();save();render(kind)})}
 function add(kind,title,text,studyRef){if(!kinds.includes(kind)||!title.trim()||!text.trim())throw Error('Title and explanation are required.');sync();const stamp=new Date().toISOString(),note={id:'note:'+crypto.randomUUID(),kind,title:title.trim(),text:text.trim(),sourceIds:[],deleted:false,createdAt:stamp,updatedAt:stamp,...(studyRef?{studyRef}:{})};state.referenceNotes.push(note);save();return note}
 return{normalize,extract,sync,render,add,edit};
})();
